    Join join2 = new Join(/* ... */);   // not a full master or newer state

    // Apply the predicate
    boolean matches1 = isFullMasterWithOlderState.test(join1);
    boolean matches2 = isFullMasterWithOlderState.test(join2);

    System.out.println("join1 matches: " + matches1); // expected: true
    System.out.println("join2 matches: " + matches2); // expected: false
